SELECT CASE WHEN budget >= 4301000 THEN 'high' WHEN budget >= 1257000 THEN 'mid' ELSE 'low' END AS budget_bucket, COUNT(CASE WHEN location = 'Chiang Mai' THEN 1 END) AS chiang_mai_count, COUNT(DISTINCT budget) AS unique_locations FROM departments WHERE budget > 2860000 GROUP BY CASE WHEN budget >= 4301000 THEN 'high' WHEN budget >= 1257000 THEN 'mid' ELSE 'low' END HAVING AVG(budget) < 2605000
